comments.suggestion_code:
extern HeapTuple row_compressor_build_tuple(RowCompressor *row_compressor);
extern void row_compressor_clear_batch(RowCompressor *row_compressor, bool changed_groups);
extern void row_compressor_append_row(RowCompressor *row_compressor, TupleTableSlot *row);

if (!AttributeNumberIsValid(count_meta_attnum))
	elog(ERROR,
		 "missing metadata column '%s' in compressed chunk",
		 COMPRESSION_COLUMN_METADATA_COUNT_NAME);

AttrNumber compressed_colnum =
	get_attnum(settings->fd.compress_relid, NameStr(attr->attname));
if (!AttributeNumberIsValid(compressed_colnum) || compressed_colnum > out_desc->natts)
	elog(ERROR,
		 "column \"%s\" not found in columnstore table",
		 NameStr(attr->attname));

AttrNumber count_metadata_column_num = InvalidAttrNumber;
for (int i = 0; i < compressed_tupdesc->natts; i++)
{
	Form_pg_attribute attr = TupleDescAttr(compressed_tupdesc, i);

	if (!attr->attisdropped &&
		strcmp(NameStr(attr->attname), COMPRESSION_COLUMN_METADATA_COUNT_NAME) == 0)
	{
		count_metadata_column_num = attr->attnum;
		break;
	}
}
